insert into public.content_items (id, type, mode_pool, domain, topics, gs_tags, event_date, body, sources, status, published_at) values
('alexandria', 'card', array['curious']::text[], 'Ancient World', array[]::text[], array[]::text[], null, '{"id":"alexandria","title":"The Library of Alexandria","category":"Ancient World","hook":"A legend of lost knowledge that still shapes how we fund science today.","scene":"For centuries, Alexandria was a port where scholars copied scrolls and argued over astronomy, medicine, and philosophy.","factBullets":["The library was an institution tied to royal patronage—not one building we can fully reconstruct from digs.","Scrolls came from Greek, Hebrew, Persian, and Indian traditions through translation and trade.","Ancient sources disagree on fires and wars that damaged collections; archaeology gives only fragments.","The myth survived the ruins and helped later cultures treat shared knowledge as a public good."],"whyItMatters":"Open-access archives and digital backups still ask who pays so one disaster cannot erase collective memory.","rabbitHole":"Which surviving ancient library—not Alexandria—actually left the largest trace on texts you can read today?","story":"The Library of Alexandria was less a single building than a evolving institution tied to Ptolemaic Egypt and later Roman rule. Scholars copied scrolls, debated astronomy, and translated texts from Hebrew, Persian, and Indian traditions. Ancient writers disagree on when fires and conflict destroyed collections—Caesar’s siege, Aurelian’s revolts, and later religious transitions all appear in the record. Archaeology offers only fragments, yet the library’s myth shaped how later cultures imagined knowledge as a public good worth protecting. Medieval monasteries, Islamic houses of wisdom, and modern universities all echo that ideal. The story persists because it names a fear we still feel: that one accident can erase centuries of collective memory and leave humanity starting over in the dark.","relevance":"Debates over open access, climate archives, and digital preservation replay the same question: who pays to keep humanity’s memory safe?"}'::jsonb, '[]'::jsonb, 'review', null),
('roman-concrete', 'card', array['curious']::text[], 'Ancient World', array[]::text[], array[]::text[], null, '{"id":"roman-concrete","title":"Roman Concrete That Outlasted Empire","category":"Ancient World","hook":"Engineers today are reverse-engineering a recipe the Romans never wrote down.","scene":"Harbor breakwaters and the Pantheon dome still stand while much modern Portland cement cracks within decades.","story":"Roman concrete structures such as the Pantheon dome and harbor breakwaters have endured for two millennia while modern Portland cement often cracks within decades. Recent studies suggest volcanic ash pozzolana and seawater triggered long-term crystal growth that heals micro-fractures—a process engineers now try to mimic in green cements. Romans treated building as empirical craft passed through guilds rather than published formulas, so the “recipe” lived in practice, not textbooks. That gap explains why Renaissance builders admired ruins without reproducing them. The contrast highlights how infrastructure knowledge can vanish even when the buildings remain standing. Today’s search for durable low-carbon materials turns back to those ash-rich mixes, proving that sustainability sometimes means recovering old chemistry rather than inventing entirely new compounds from scratch every generation.","relevance":"Climate policy pushes low-carbon cement; Roman methods offer models that pair longevity with lower emissions.","rabbitHole":"Why did medieval Europeans quarry Roman ruins for lime instead of copying their mortar chemistry?"}'::jsonb, '[]'::jsonb, 'review', null),
('silk-road', 'card', array['curious']::text[], 'Ancient World', array[]::text[], array[]::text[], null, '{"id":"silk-road","title":"The Silk Road Was Never One Road","category":"Ancient World","hook":"Caravans, ships, and credit networks linked continents long before “globalization” became a buzzword.","scene":"Oasis cities and ocean ports tied steppe, desert, and maritime lanes into overlapping trade circuits across Afro-Eurasia.","story":"Historians now speak of Silk Roads in the plural: shifting routes across steppes, deserts, and Indian Ocean ports that moved silk, spices, silver, Buddhism, Islam, and plague alike. No single emperor controlled the whole network; instead, oasis cities, nomadic confederations, and merchant families negotiated passage. Paper and printing traveled west while glass and grapes moved east. Disease followed the same paths—the Black Death’s speed reflects how connected Afro-Eurasia already was in the fourteenth century. Romantic images of camel caravans capture one slice, but maritime lanes often carried higher volume with lower cost per bolt of cloth. Understanding the network as many overlapping circuits helps explain why trade wars, sanctions, and chokepoints like the Strait of Malacca still dominate headlines: logistics is geopolitics with a ledger.","relevance":"Supply-chain resilience and “friend-shoring” are modern names for ancient routing dilemmas around trust, distance, and tolls.","rabbitHole":"How did Sogdian merchants act as bankers across languages without a shared central bank?"}'::jsonb, '[]'::jsonb, 'review', null),
('black-death', 'card', array['curious']::text[], 'Medieval', array[]::text[], array[]::text[], null, '{"id":"black-death","title":"When the Black Death Rewired Europe","category":"Medieval","hook":"A pandemic did not just kill—it reshaped wages, faith, and the map of power.","scene":"In the mid-1300s, plague moved along trade routes and hit crowded towns and farms across Eurasia within a few years.","factBullets":["Estimates suggest roughly a third of Europe’s people died in the first wave; regions varied widely.","Fewer workers meant higher wages and weaker serf obligations in many places.","Cities saw guilds and councils gain leverage as elites competed for mobile taxpayers.","Art, sermons, and riots reflected both fear and anger at institutions that could not stop the dying."],"whyItMatters":"Sudden death still reshapes labor markets and trust in institutions—historians call it shock that accelerates trends already underway.","rabbitHole":"Did plague-driven wage gains in England truly begin the long decline of serfdom, or did law change first?","story":"The plague that swept Eurasia in the mid-fourteenth century killed perhaps a third of Europe’s population within a few years. Labor scarcity suddenly gave surviving peasants leverage: wages rose, serfdom weakened, and landlords struggled to enforce old dues. In cities, guilds and councils gained voice as elites competed for taxpayers who could flee. Religious fervor spiked—flagellants, scapegoating of minorities, and vivid art of death—yet institutional Christianity also faced awkward questions about why prayers failed. The demographic shock accelerated shifts already underway, including the spread of gunpowder weapons and the appeal of printed texts after Gutenberg. Historians debate how much the plague “caused” versus “accelerated,” but the pattern is familiar: mass mortality rearranges who must be paid, who can organize, and which stories societies tell to make sense of sudden loss.","relevance":"Post-COVID labor shortages and housing debates echo medieval negotiations over who owes whom a living."}'::jsonb, '[]'::jsonb, 'review', null),
('magna-carta', 'card', array['curious']::text[], 'Medieval', array[]::text[], array[]::text[], null, '{"id":"magna-carta","title":"Magna Carta’s Messy Birth","category":"Medieval","hook":"A peace treaty born from baronial rage became a symbol lawyers far away would later reinvent.","scene":"In 1215 rebellious English barons forced King John to seal concessions at Runnymede—mostly feudal fines, not abstract liberty.","story":"King John sealed Magna Carta in 1215 not to proclaim universal rights but to buy time from rebellious barons furious over taxes and failed wars in France. Most clauses concern feudal fines, fish weirs, and widow remarriage—not abstract liberty. The document was annulled within weeks, reissued in edited forms, and largely forgotten until seventeenth-century English lawyers mined it during fights with Stuart kings. American revolutionaries and civil-rights advocates later quoted those reinterpretations more than the original text. The gap between medieval grievance list and modern myth shows how societies retro-fit founding stories when they need limits on power. Magna Carta matters today less as a precise law than as evidence that forcing rulers to sign concessions can seed centuries of argument about whether anyone, including executives, stands above agreed rules.","relevance":"Executive orders, emergency powers, and court challenges still circle the question Magna Carta raised: who checks the checker?","rabbitHole":"Which Magna Carta clause stayed on English statute books the longest without being repealed?"}'::jsonb, '[]'::jsonb, 'review', null),
('gothic-cathedral', 'card', array['curious']::text[], 'Medieval', array[]::text[], array[]::text[], null, '{"id":"gothic-cathedral","title":"Gothic Cathedrals as Public Works","category":"Medieval","hook":"Stone lace and stained glass were also Europe’s largest crowd-funded infrastructure projects.","scene":"For generations, cathedral cities raised pointed arches and bright choirs with guild gifts, indulgence sales, and skilled migrant labor.","story":"Building a Gothic cathedral could span generations, employing quarrymen, glassmakers, and sculptors whose names rarely survived. Cities competed for taller naves and brighter choirs, using pointed arches and flying buttresses to redirect weight outward, freeing walls for enormous windows. Funding mixed bishoprics, guild donations, indulgence sales, and local pride—everyone saw the skyline rise. Laborers learned on site, spreading techniques region to region like an open-source codebase. Accidents, wars, and funding gaps left many churches half-finished for centuries, reminding us that even “timeless” monuments are incremental. The spiritual goal was to lift eyes toward transcendence, but the economic effect was equally real: steady wages, pilgrimage traffic, and craft specialization. Modern megaprojects—from stadiums to transit hubs—reuse that blend of civic identity, debt, and the promise that future visitors will admire what present taxpayers endure.","relevance":"Infrastructure bills still sell bridges and parks as shared heritage, not just steel and concrete.","rabbitHole":"How did medieval builders calculate load without modern structural math—and where did they fail?"}'::jsonb, '[]'::jsonb, 'review', null),
('printing-press', 'card', array['curious']::text[], 'Renaissance', array[]::text[], array[]::text[], null, '{"id":"printing-press","title":"Gutenberg’s Press and the Info Explosion","category":"Renaissance","hook":"Movable type did not create literacy overnight, but it changed who could argue in public.","scene":"Around 1450 in Mainz, craftsmen combined metal type, oil ink, and a screw press to print pages in quantity.","factBullets":["Early profits came from Bibles and indulgence forms, then pamphlets and maps spread in weeks, not months.","Rulers and churches used print for propaganda—and quickly added censorship and licensing.","Literacy rose slowly; the bigger shift was many competing voices entering public debate.","Historians compare print to the internet because copying got cheap and elites lost control of the narrative."],"whyItMatters":"Every cheap-copy medium since—from radio to social feeds—reopens fights over rumor, authorship, and amplification.","rabbitHole":"Which technology—print or postal networks—spread Reformation ideas faster across Germany?","story":"Johannes Gutenberg’s mid-fifteenth-century press combined oil-based ink, adjustable metal type, and a modified wine press to reproduce texts faster than scribes could copy them. Bibles and indulgence forms paid early bills, yet the real shift was pamphlets, maps, and scientific diagrams reaching merchants, students, and reformers within weeks. Catholic and Protestant leaders alike harnessed print for propaganda while censorship and licensing followed almost immediately—every information revolution triggers a counter-revolution in control. Literacy rates climbed slowly; the deeper change was the volume of competing voices. Empires used printed atlases to claim territory; alchemists shared recipes; women readers entered new literary markets. Historians compare the press to the internet not because effects were identical, but because both collapsed copying costs and forced elites to share narrative power with strangers they could not fully monitor or silence.","relevance":"Social feeds and AI-generated text replay Gutenberg-era fights over authorship, rumor, and who gets amplified."}'::jsonb, '[]'::jsonb, 'review', null),
('constantinople-1453', 'card', array['curious']::text[], 'Renaissance', array[]::text[], array[]::text[], null, '{"id":"constantinople-1453","title":"The Fall of Constantinople, 1453","category":"Renaissance","hook":"Cannons breached ancient walls—and rerouted minds, maps, and migration.","scene":"Ottoman bronze guns punched through Constantinople’s Theodosian walls during a seven-week siege in 1453.","story":"Ottoman forces under Mehmed II captured Constantinople after a seven-week siege that showcased enormous bronze guns punching holes through Theodosian walls once deemed impregnable. The city’s fall ended the Eastern Roman Empire, yet Greek scholars had already been fleeing west with manuscripts that fed Italian humanism. Ottoman sultans preserved many churches as mosques while rebuilding the urban economy, positioning the city as a hub between Europe, Asia, and Africa. Christian Europe interpreted the loss as apocalyptic, spurring exploration to find new trade routes and allies. Russian rulers later claimed Moscow as a “third Rome,” weaving religion into geopolitics for centuries. The event shows how a single siege can symbolize epoch change even while daily life—markets, families, neighborhoods—continues under new flags. Borders on maps redraw faster than identities in streets.","relevance":"Wars that seize capitals still send refugee scholars, art, and code repositories across borders within days.","rabbitHole":"How many Greek scholars actually reached Italy before 1453 versus after—and does it matter for Renaissance timing?"}'::jsonb, '[]'::jsonb, 'review', null),
('da-vinci-notebooks', 'card', array['curious']::text[], 'Renaissance', array[]::text[], array[]::text[], null, '{"id":"da-vinci-notebooks","title":"Leonardo’s Notebooks as R&D Labs","category":"Renaissance","hook":"Sketches of wings and waterways reveal a mind treating art and engineering as one discipline.","scene":"Mirror writing, anatomy studies, and machine sketches filled Leonardo’s notebooks while patrons funded court spectacles and siege designs.","story":"Leonardo da Vinci filled thousands of pages with mirror writing, anatomy studies, hydraulic gears, and theatrical machines for court spectacles. Patronage from Milan and Florence funded experiments without modern patents; secrecy protected competitive advantage in siege engines and pageantry alike. Many designs—helicopter precursors, diving suits—were never built at scale, yet they document systematic observation: dissections informed painting muscles, while painting taught him how light reveals form. After his death, scattered notebooks escaped publication for centuries, so innovations died with the pages. That loss underscores how progress depends on circulation, not genius alone. Renaissance workshops functioned like startups: iterate quickly, demo for investors, pivot when wars shifted budgets. Leonardo’s blend of visualization and measurement anticipates today’s design thinking, reminding us that breakthroughs often start as marginal doodles someone almost threw away.","relevance":"Lab notebooks, Git commits, and design figma files are modern heirs to Leonardo’s marginalia—if anyone archives them.","rabbitHole":"Which of Leonardo’s built machines actually worked under test, not just on paper?"}'::jsonb, '[]'::jsonb, 'review', null),
('scientific-revolution', 'card', array['curious']::text[], 'Enlightenment', array[]::text[], array[]::text[], null, '{"id":"scientific-revolution","title":"The Scientific Revolution’s Quiet Radicalism","category":"Enlightenment","hook":"Measuring planets and pumping air out of jars challenged who got to declare truth.","scene":"Telescopes, elliptical orbits, and vacuum pumps let observers test claims against measurement—not only ancient authority.","story":"From Copernicus to Newton, sixteenth- and seventeenth-century thinkers proposed that mathematics and experiment could describe nature more reliably than ancient authority alone. Galileo’s telescopes, Kepler’s ellipses, and Boyle’s vacuum pumps were tools, but also political acts: they implied that any careful observer might check claims. Institutions like the Royal Society formalized peer critique—letters, demonstrations, replicated trials—long before modern journals. Church and state sometimes punished heterodox views, yet merchants funding navigation and mining wanted accurate tables regardless of theology. The revolution was uneven; alchemy and astrology lingered beside calculus. Still, the shift toward testable hypotheses seeded technologies from precision clocks to industrial chemistry. Enlightenment philosophes exported the story as triumph over superstition, simplifying messy debates. What endured was a method: show your work, invite falsification, and treat nature as something humans can model without exhausting its mystery.","relevance":"Climate models and vaccine trials inherit the same social contract: trust requires transparent methods others can rerun.","rabbitHole":"Did Newton’s alchemy manuscripts change how historians date the “scientific” Newton we teach in schools?"}'::jsonb, '[]'::jsonb, 'review', null),
('enlightenment-salons', 'card', array['curious']::text[], 'Enlightenment', array[]::text[], array[]::text[], null, '{"id":"enlightenment-salons","title":"Salons Where Ideas Went Viral","category":"Enlightenment","hook":"Before Twitter threads, hosted conversations spread reform across European cities.","scene":"In eighteenth-century Paris and London, hostesses seated writers, diplomats, and financiers in private parlors to debate reform.","story":"In eighteenth-century Paris and London, salons gathered writers, financiers, diplomats, and aristocrats in private parlors to debate commerce, education, and legal reform. Hostesses such as Madame Geoffrin curated seating so rivals might actually listen, turning status into a platform. Encyclopedists circulated proofs before publication; music and theater provided cover for political barbs censorship would otherwise ban. Salons were exclusive—race, gender, and class limits meant most people never entered—yet ideas leaked through pamphlets and correspondence networks that functioned like slow-motion feeds. Monarchs sometimes patronized the same thinkers they later imprisoned when revolutions erupted. The format shows how intellectual change often rides social infrastructure: who invites whom, who pays printing costs, who translates across languages. Public sphere theory grew from these imperfect rooms, reminding us that “open discourse” has always depended on gatekeepers willing to open doors at all.","relevance":"Podcasts, Substacks, and invite-only group chats reproduce salon dynamics—with similar exclusion risks.","rabbitHole":"Which Enlightenment policy change first traced directly to a salon introduction rather than a published book?"}'::jsonb, '[]'::jsonb, 'review', null),
('haitian-revolution', 'card', array['curious']::text[], 'Enlightenment', array[]::text[], array[]::text[], null, '{"id":"haitian-revolution","title":"Haiti’s Revolution Rewrote Freedom","category":"Enlightenment","hook":"Enslaved rebels defeated empires and forced the Atlantic world to confront its own slogans.","scene":"On Saint-Domingue’s sugar plantations, uprisings from 1791 onward defeated French, British, and Spanish forces by 1804.","story":"The Haitian Revolution (1791–1804) began with uprisings on sugar plantations and ended with an independent Black republic defeating French, British, and Spanish forces. Leaders like Toussaint Louverture and Jean-Jacques Dessalines navigated alliances, constitutions, and brutal counterinsurgency while Europe debated liberty in Paris. Victory terrified slaveholding nations, prompting embargoes, debt imposed on Haiti for recognition, and silencing in textbooks for generations. Yet the event proved Enlightenment rhetoric could not be contained to white property owners; colonized people repurposed the same language as a weapon. Independence came at catastrophic cost—war, famine, and later authoritarian rule—but it permanently shifted fear and strategy in the Americas, including Napoleon’s sale of Louisiana. Haiti’s story challenges narratives that treat 1776 or 1789 as freedom’s finish line. It remains a case study in how international finance and racism punish victories that threaten profitable atrocities.","relevance":"Reparations debates and debt relief for Haiti connect directly to nineteenth-century punishment for successful emancipation.","rabbitHole":"How much did fear of Haiti’s example shape the timing of abolition in British colonies versus moral campaigns alone?"}'::jsonb, '[]'::jsonb, 'review', null),
('industrial-mills', 'card', array['curious']::text[], 'Modern Era', array[]::text[], array[]::text[], null, '{"id":"industrial-mills","title":"Mill Towns and the Clock of Industry","category":"Modern Era","hook":"Factory bells synchronized bodies before smartphones synchronized attention.","scene":"Steam-powered textile mills drew workers into company towns where bells, piece rates, and shift work replaced craft autonomy.","story":"Britain’s Industrial Revolution concentrated workers in textile mills where steam power and division of labor boosted output while shortening craft autonomy. Company towns supplied housing tied to wages; child labor and sixteen-hour shifts drew reformers who photographed injuries and pushed early factory acts. Unions formed slowly amid criminalization of “combinations,” yet strikes spread along rail lines carrying news faster than magistrates could respond. Pollution darkened rivers; urban populations exploded without sewers, feeding cholera cycles later solved by public health engineering. Owners argued markets would self-correct; critics replied that bargaining power was never equal when hunger waited outside the gate. The era forged modern GDP growth curves and modern inequality debates simultaneously. Understanding mills clarifies why labor law, zoning, and environmental regulation exist: they respond to real harms when production scales faster than community guardrails.","relevance":"Warehouse algorithms and gig-worker ratings extend clock discipline into pockets via apps instead of bell towers.","rabbitHole":"Which single factory reform law measurably cut child injury rates first—and how was it enforced?"}'::jsonb, '[]'::jsonb, 'review', null),
('ww1-telegraph', 'card', array['curious']::text[], 'Modern Era', array[]::text[], array[]::text[], null, '{"id":"ww1-telegraph","title":"World War I as a Wired War","category":"Modern Era","hook":"Telegraphs and railways turned strategy into a race against timetables—and tragedy.","scene":"Mobilization plans tied army deployments to railway schedules while telegraph cables compressed diplomatic decision cycles.","story":"World War I linked mobilization plans to railway schedules so tightly that diplomatic delays could not slow mechanical deployment once set in motion. Telegraph cables carried orders across continents within minutes, compressing decision cycles while misread messages still sent millions marching. Trench stalemate emerged partly because defense benefited from barbed wire, machine guns, and rapid artillery correction via phone lines. Propaganda offices used mass print and early film to sustain morale; poets and nurses documented psychological wounds medicine barely understood. Empires collapsed—Ottoman, Austro-Hungarian, Russian—redrawing maps through treaties drawn far from affected villages. Chemical weapons, colonial troop levies, and blockade starvation showed total war consuming civilians as resources. The conflict’s technology story warns that connectivity accelerates both coordination and catastrophe when leaders treat mobilization scripts as destiny rather than choice.","relevance":"Cyber commands and instant satellite imagery update WWI’s lesson: speed without pause breeds escalation traps.","rabbitHole":"Did the July Crisis unfold faster because telegraphs removed sleep gaps diplomats once relied on?"}'::jsonb, '[]'::jsonb, 'review', null),
('berlin-wall', 'card', array['curious']::text[], 'Modern Era', array[]::text[], array[]::text[], null, '{"id":"berlin-wall","title":"Berlin Wall as Cold War Interface","category":"Modern Era","hook":"Concrete split a city—and became the screen onto which rivals projected their stories.","scene":"East Berlin sealed crossing points overnight in August 1961, splitting streets, families, and even ghosted subway stations.","story":"East Germany sealed Berlin overnight in August 1961 to stop mass emigration westward, turning streets into death strips guarded by towers and dogs. The wall was less a military fortification than a migration dam: it trapped people inside a system losing legitimacy through comparison. Western media turned graffiti-covered segments into symbols of creative freedom; Eastern propaganda called it an antifascist barrier. Families split; subway lines ghosted through sealed stations. Over decades, micro-protests—church groups, punk bands, environmental circles—eroded trust in the regime until 1989 checkpoints opened amid confusion and celebration. Pieces of the wall now sit in museums worldwide, sometimes romanticizing collapse while forgetting economic shocks that followed reunification. The episode teaches that borders are information tools: they signal who may leave, who must stay, and which version of history counts on each side of the concrete.","relevance":"Border walls and visa regimes still manage inequality of movement more than military invasion risk.","rabbitHole":"How much did satellite TV and VHS tapes undermine East German loyalty before the wall physically fell?"}'::jsonb, '[]'::jsonb, 'review', null),
('germ-theory', 'card', array['curious']::text[], 'Science & Invention', array[]::text[], array[]::text[], null, '{"id":"germ-theory","title":"Germ Theory and the Invisible Enemy","category":"Science & Invention","hook":"Handwashing went from ridicule to hospital policy once microbes became visible enough to believe.","scene":"In 1840s Vienna, Ignaz Semmelweis cut maternity deaths with chlorine handwashing while many physicians dismissed the practice.","story":"Ignaz Semmelweis noticed maternity wards with doctor-led autopsies had higher death rates than midwife wards; chlorine handwashing cut fatalities dramatically in 1840s Vienna. Contemporaries mocked him—without a accepted mechanism, the practice seemed superstitious. Pasteur and Koch later linked specific bacteria to disease, giving public health a target: sewage separation, pasteurized milk, vaccination campaigns. Cities rebuilt water systems; surgeons adopted antiseptic routines that made complex operations survivable. Germ theory also justified coercive measures—from quarantines to residential redlining labeled “hygiene”—showing how science interfaces with power. Acceptance took decades because it required retraining professions whose status rested on old humoral models. The arc from Semmelweis’s ostracism to COVID-era hand-sanitizer stations illustrates how evidence alone rarely changes behavior without institutions, storytelling, and peer pressure aligned behind inconvenient truths.","relevance":"Misinformation fights during pandemics replay nineteenth-century battles over who counts as an credible expert voice.","rabbitHole":"Why did germ theory spread faster in colonial army hospitals than in European civilian clinics at first?"}'::jsonb, '[]'::jsonb, 'review', null),
('ada-lovelace', 'card', array['curious']::text[], 'Science & Invention', array[]::text[], array[]::text[], null, '{"id":"ada-lovelace","title":"Ada Lovelace Imagined Software","category":"Science & Invention","hook":"Before computers existed, she described machines that could compose music—not just crunch numbers.","scene":"In the 1840s Ada Lovelace annotated Charles Babbage’s Analytical Engine and described instructions separate from the hardware itself.","story":"Ada Lovelace, working with Charles Babbage’s Analytical Engine designs in the 1840s, wrote notes envisioning a device manipulating symbols beyond arithmetic—music, logic, potentially any rule-based pattern. She distinguished the machine’s hardware from the instructions fed into it, an early sketch of what later generations called software. Babbage never built the full engine; Lovelace’s ideas circulated quietly among mathematicians until twentieth-century programmers rediscovered them during debates over women’s roles in computing. Her social world mixed Romantic poetry and industrial ambition—Byron’s daughter meeting factory precision. Historians caution against mythmaking: Lovelace was one voice in a broader conversation, and some technical claims remain disputed. Still, her emphasis on creativity within computation foreshadowed modern coding culture where art and engineering share repositories. Remembering her clarifies that imagination often precedes hardware by a century.","relevance":"Prompt engineering and generative AI reopen Lovelace’s question: where does instruction end and authorship begin?","rabbitHole":"Which part of Lovelace’s “Note G” do historians still argue was originally Babbage’s idea versus hers?"}'::jsonb, '[]'::jsonb, 'review', null),
('green-revolution', 'card', array['curious']::text[], 'Science & Invention', array[]::text[], array[]::text[], null, '{"id":"green-revolution","title":"The Green Revolution’s Double Harvest","category":"Science & Invention","hook":"High-yield wheat fed millions—and reshaped politics of water, seed, and debt.","scene":"Dwarf wheat and rice varieties paired with fertilizer and irrigation doubled yields across Mexico, India, and the Philippines in the 1960s–70s.","story":"In the 1960s and 70s, researchers led by Norman Borlaug bred dwarf wheat and rice varieties that responded heavily to fertilizer, dramatically raising yields in Mexico, India, and the Philippines. Famines eased; governments celebrated self-sufficiency. Yet the package required irrigation, pesticides, and credit for inputs—benefiting large farmers first and deepening groundwater stress where pumps ran unchecked. Seed sovereignty debates erupted when proprietary strains replaced locally adapted landraces farmers once saved each season. The revolution prevented starvation for many while tying food security to fossil-fuel-based inputs now vulnerable to climate shocks. Critics note distribution, not production alone, causes hunger; supporters point to lives saved before social safety nets caught up. The story is a template for tech fixes with uneven dividends: breakthrough biology plus institutions determine whether abundance becomes justice or new dependency chains exported through trade agreements.","relevance":"CRISPR crops and vertical farms repeat the question: who owns the seed when the climate turns hostile?","rabbitHole":"Did Indian Punjab’s water table collapse begin during Green Revolution expansion or earlier canal policies?"}'::jsonb, '[]'::jsonb, 'review', null),
('jazz-migration', 'card', array['curious']::text[], 'Culture & Society', array[]::text[], array[]::text[], null, '{"id":"jazz-migration","title":"Jazz and the Great Migration","category":"Culture & Society","domain":"History","hook":"Sound carried stories north when Jim Crow blocked so many other paths.","scene":"Between the 1910s and 1970s, Black musicians carried blues and brass traditions into northern cities, clubs, and recording studios.","story":"Between the 1910s and 1970s, millions of African Americans left the rural South for northern and western cities, carrying musical traditions that fused blues, ragtime, brass bands, and Caribbean rhythms into jazz. Chicago, Kansas City, and New York clubs became laboratories where improvisation met recording technology, spreading Louis Armstrong and Duke Ellington to radios worldwide. Migration was economic and political escape—from sharecropping contracts to factory wages—yet redlining and violence met arrivals in new forms. Jazz became both entertainment and subtle commentary: swing for dance floors, bebop for virtuosos asserting intellectual freedom. Critics debated authenticity while audiences crossed color lines in segregated rooms. The genre influenced classical composers, film scores, and later hip-hop sampling ethics. Cultural history here shows movement of people reshapes art faster than any single genius narrative; infrastructure—clubs, labels, trains—matters as much as melody.","relevance":"Global streaming playlists still trace diaspora paths jazz pioneered, raising who profits from roots music today.","rabbitHole":"Which 1920s recording technology change did more for jazz diffusion: radio or the electric microphone?"}'::jsonb, '[]'::jsonb, 'review', null),
('un-declaration', 'card', array['curious']::text[], 'Culture & Society', array[]::text[], array[]::text[], null, '{"id":"un-declaration","title":"Writing Universal Human Rights in 1948","category":"Culture & Society","hook":"Forty-eight nations signed aspirations—not enforceable law—and changed the vocabulary of justice.","scene":"In 1948 UN committees drafted thirty articles on dignity and rights that member states endorsed without binding courts attached.","story":"The Universal Declaration of Human Rights emerged from United Nations committees chaired by Eleanor Roosevelt alongside diplomats from Chile, China, Lebanon, and others drafting articles on dignity, speech, asylum, and education. It was not a treaty with courts attached; superpowers still held empires and segregated citizens at home. Yet the text gave activists a shared lexicon to challenge apartheid, gender discrimination, and torture with phrases governments themselves had endorsed on paper. Cold War rivals each claimed to fulfill rights while accusing opponents of violations—a propaganda game that nonetheless legitimized monitoring NGOs. Later covenants tried to add teeth through reporting mechanisms, though enforcement remains uneven. The declaration’s power is rhetorical and legal scaffolding: courts cite it; movements wave it. Studying its birth reveals how compromise language—“free and equal”—can become a weapon for the marginalized when archives prove hypocrisy.","relevance":"Digital privacy charters and AI ethics frameworks copy the UDHR playbook: declare norms before enforcement exists.","rabbitHole":"Which UDHR article provoked the most delegate walkouts during drafting—and what compromise survived?"}'::jsonb, '[]'::jsonb, 'review', null),
('opportunity-cost', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"opportunity-cost","title":"Opportunity Cost in Plain Terms","domain":"Economics","format":"Explainer","hook":"Every “yes” to one option is a quiet “no” to another—and economists gave that tradeoff a name.","scene":"You can spend an hour studying, working, or resting—but not all three at once.","coreFact":"Opportunity cost is the value of the next-best alternative you give up when you choose something. It is not always money: time, attention, and risk count too. Businesses use it when comparing projects; governments use it when budgeting public land or staff hours. The idea clarifies why “free” choices still have costs somewhere in the system.","whyItMatters":"Budget headlines and product roadmaps hide tradeoffs; naming opportunity cost makes debates about priorities more precise.","rabbitHole":"Why did early economists tie opportunity cost to forgone utility rather than only forgone cash?"}'::jsonb, '[]'::jsonb, 'review', null),
('inflation-basket', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"inflation-basket","title":"How an Inflation “Basket” Works","domain":"Economics","format":"Explainer","hook":"Inflation numbers come from a shopping list—not from every price in the economy at once.","scene":"Statisticians track a sample of goods and services that typical households buy over time.","coreFact":"Consumer price indexes weight items like housing, food, transport, and medical care according to survey data. When the basket’s total cost rises compared with a base year, reported inflation goes up. Method tweaks—which items enter, how quality changes are adjusted—can shift the index slightly even when lived experience feels different.","whyItMatters":"Wage clauses, bond yields, and benefit adjustments often peg to these indexes, so their design affects millions of contracts.","rabbitHole":"How do statistical agencies treat products that improve rapidly, like smartphones, without double-counting quality?"}'::jsonb, '[]'::jsonb, 'review', null),
('comparative-advantage', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"comparative-advantage","title":"Comparative Advantage Without Jargon","domain":"Economics","format":"Explainer","hook":"Countries still trade when one could make everything “cheaper”—because relative efficiency matters.","scene":"Two regions can each focus on what they sacrifice least to produce, then swap the rest.","coreFact":"Comparative advantage says gains from trade come from differences in opportunity costs, not from being best at everything. Even if one place is more productive across the board, both sides can benefit by specializing where their relative efficiency is highest and trading for the rest. The model assumes trade is voluntary and costs of transport stay manageable.","whyItMatters":"Supply chains and tariff debates often confuse “who is fastest” with “who gives up less”—this idea separates the two.","rabbitHole":"What assumptions break comparative advantage when supply chains face sudden embargoes or bottlenecks?"}'::jsonb, '[]'::jsonb, 'review', null),
('money-multiplier', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"money-multiplier","title":"Why Banks Lend More Than Their Vault Cash","domain":"Economics","format":"Explainer","hook":"A deposit can ripple through the banking system under rules set by regulators—not by unlimited magic.","scene":"When you deposit money, the bank keeps a required fraction in reserve and lends the rest.","coreFact":"Fractional reserve banking means institutions hold only part of deposits as central-bank reserves and allocate the remainder to loans or securities, within capital and liquidity rules. Repaid loans can become new deposits elsewhere, so the money supply can grow through lending activity. Central banks influence the pace through reserve requirements, interest rates, and supervision.","whyItMatters":"Credit availability, housing markets, and crisis responses all connect to how tightly this lending loop is supervised.","rabbitHole":"How did post-2008 reforms change the link between reserves and lending compared with textbook multiplier stories?"}'::jsonb, '[]'::jsonb, 'review', null),
('rain-shadow', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"rain-shadow","title":"Rain Shadows and Dry Leeward Slopes","domain":"Geography","format":"Explainer","hook":"One side of a mountain range can be lush while the other looks like a desert—for predictable reasons.","scene":"Moist air climbs a range, cools, drops rain, and descends warmer and drier on the far side.","coreFact":"Rain-shadow deserts form when prevailing winds push air upslope. Water vapor condenses and falls as precipitation on the windward side. Leeward air compresses and heats, raising its capacity to hold moisture without raining. Examples appear worldwide wherever tall barriers sit across dominant wind flows.","whyItMatters":"Farm planning, wildfire risk, and city water sources often depend on which side of a range a community occupies.","rabbitHole":"Which coast ranges create the sharpest rain-shadow contrast relative to their height?"}'::jsonb, '[]'::jsonb, 'review', null),
('plate-boundaries', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"plate-boundaries","title":"Three Ways Plates Meet","domain":"Geography","format":"Map","hook":"Earth’s surface is a slow puzzle of moving plates—and their edges explain quakes and volcanoes.","scene":"Geologists map divergent, convergent, and transform boundaries where plates slide, collide, or pull apart.","coreFact":"At divergent boundaries, plates separate and magma can create new crust, as along mid-ocean ridges. Convergent boundaries squeeze crust, building mountains and trenches. Transform boundaries slide past each other, storing stress released in earthquakes. Hot spots can punch through plates away from edges, forming island chains.","whyItMatters":"Building codes, tsunami planning, and mineral deposits all trace back to which boundary type lies nearby.","rabbitHole":"Why do some subduction zones produce more explosive volcanoes than others?"}'::jsonb, '[]'::jsonb, 'review', null),
('monsoon-pattern', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"monsoon-pattern","title":"What Drives a Monsoon","domain":"Geography","format":"Explainer","hook":"Monsoons are seasonal wind reversals—not just “a lot of rain in summer.”","scene":"Land heats faster than ocean, shifting pressure and pulling moisture-laden air inland for months.","coreFact":"Monsoon systems arise from differential heating between continents and surrounding seas. Warm land lowers pressure, drawing in humid maritime air that rises, cools, and produces seasonal rains. Winter often reverses the flow, bringing drier conditions. Agriculture across South Asia, West Africa, and parts of the Americas paces planting to these rhythms.","whyItMatters":"Food prices and hydropower output swing with monsoon timing, even for countries far from the farms affected.","rabbitHole":"How do El Niño events shift monsoon onset dates in measurable ways?"}'::jsonb, '[]'::jsonb, 'review', null),
('exclusive-economic-zone', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"exclusive-economic-zone","title":"Coastal Waters and EEZs","domain":"Geography","format":"Institution","hook":"Nations claim more than their beaches—they claim bands of ocean under international rules.","scene":"From shore outward, zones define who manages fish, seabed resources, and shipping rights.","coreFact":"Under the UN Convention on the Law of the Sea framework, an Exclusive Economic Zone generally extends up to 200 nautical miles from a baseline coast. Coastal states hold rights to explore and manage living and non-living resources in the water column and seabed, while other nations retain navigation and overflight freedoms. Overlaps and straits create negotiated exceptions.","whyItMatters":"Fishing quotas, offshore wind leases, and submarine cable routes all intersect these mapped zones.","rabbitHole":"How are EEZ boundaries drawn when coasts face each other across less than 400 nautical miles?"}'::jsonb, '[]'::jsonb, 'review', null),
('separation-of-powers', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"separation-of-powers","title":"Separating Powers in Modern States","domain":"Civics","format":"Institution","hook":"Many constitutions split government into branches so no single office holds every lever.","scene":"Legislatures write rules, executives carry them out, and courts interpret disputes—ideally with checks between them.","coreFact":"Separation of powers distributes lawmaking, enforcement, and adjudication across institutions. Checks such as veto power, judicial review, or legislative oversight aim to limit overreach. Designs vary: parliamentary systems fuse executive and legislative majorities more tightly than presidential ones. The goal is procedural balance, not guaranteed agreement.","whyItMatters":"Court cases, emergency orders, and budget fights make more sense when you know which branch owns which step.","rabbitHole":"Which democracies blend parliamentary and presidential features, and why?"}'::jsonb, '[]'::jsonb, 'review', null),
('jury-system', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"jury-system","title":"What Juries Are For","domain":"Civics","format":"Institution","hook":"Randomly chosen citizens still decide facts in many courtrooms—a practice with ancient roots.","scene":"Eligible residents receive summons, hear evidence under judge guidance, and return verdicts in serious trials.","coreFact":"Trial juries apply law to facts in criminal and some civil cases. Judges instruct on legal standards; jurors deliberate privately. Rules on unanimity, jury size, and eligible offenses differ by jurisdiction. Supporters cite community legitimacy; critics note complexity bias and representation challenges. Many countries use bench trials instead for some matters.","whyItMatters":"News about high-profile trials often skips procedural rules that actually constrain what jurors may consider.","rabbitHole":"How do continental European systems handle fact-finding without lay juries in most cases?"}'::jsonb, '[]'::jsonb, 'review', null),
('census-count', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"census-count","title":"Why Countries Run Censuses","domain":"Civics","format":"Institution","hook":"A national head count redraws maps, budgets, and research baselines for a decade or more.","scene":"Household forms and field enumerators collect age, housing, and location data on a set census day or period.","coreFact":"Censuses provide denominators for representation formulas, equalization payments, and urban planning. Statisticians publish anonymized tabulations while guarding individual privacy through suppression rules. Undercounts in remote or mobile populations can skew funding unless corrected with follow-up surveys. Many nations now blend traditional forms with administrative records.","whyItMatters":"School seat projections, transit grants, and public-health rates often start from census blocks.","rabbitHole":"What statistical techniques fix undercount bias without revealing private responses?"}'::jsonb, '[]'::jsonb, 'review', null),
('public-records-laws', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"public-records-laws","title":"Public Records and Transparency Laws","domain":"Civics","format":"Explainer","hook":"Many governments must release documents on request—within written exceptions.","scene":"Citizens, journalists, and researchers file forms asking for emails, contracts, or inspection reports.","coreFact":"Freedom-of-information statutes set timelines for agencies to respond and list exemptions such as active law-enforcement investigations, personal privacy, or national-security classifications. Fees may cover copying costs. Appeals bodies or courts resolve disputes when agencies withhold material. Scope varies: some regimes cover all public bodies; others exclude courts or legislators.","whyItMatters":"Environmental spills, procurement scandals, and safety audits often surface first through records requests, not press releases.","rabbitHole":"How do “sunshine” laws differ for local municipalities versus national ministries?"}'::jsonb, '[]'::jsonb, 'review', null),
('how-wifi-works', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"how-wifi-works","title":"Wi‑Fi Is a Radio Link, Not the Internet","domain":"Technology","format":"Explainer","hook":"Your router speaks radio to your phone; the wider internet usually rides on cables or fiber beyond it.","scene":"Data packets hop from device to access point, then through a modem and ISP network toward servers.","coreFact":"Wi‑Fi uses standardized radio protocols in unlicensed bands to link devices to a local router. The router forwards frames to a modem or gateway that connects to an internet service provider. Speed drops with distance, walls, and interference from neighbors’ networks. Security relies on encryption protocols configured on the access point.","whyItMatters":"Home slowdowns often come from local wireless congestion, not from “the whole internet” failing.","rabbitHole":"Why did Wi‑Fi move from 2.4 GHz toward 5 GHz and 6 GHz bands for capacity?"}'::jsonb, '[]'::jsonb, 'review', null),
('qr-code-basics', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"qr-code-basics","title":"How QR Codes Pack Data","domain":"Technology","format":"Explainer","hook":"Those square barcodes are readable even when partly damaged—by design.","scene":"Cameras scan black-and-white modules; error correction rebuilds missing pieces into URLs or text.","coreFact":"QR codes store bits in a grid with finder patterns for orientation. Reed–Solomon error correction adds redundant data so smudged labels still decode. Payloads can be URLs, payment tokens, or Wi‑Fi join credentials. The standard defines version sizes and masking patterns to balance density and scan reliability.","whyItMatters":"Ticketing, menus, and device pairing exploded after smartphones shipped cameras that decode QR natively.","rabbitHole":"How much data can the largest QR versions hold compared with traditional UPC barcodes?"}'::jsonb, '[]'::jsonb, 'review', null),
('gps-satellite-timing', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"gps-satellite-timing","title":"GPS Needs Atomic Clocks in Space","domain":"Technology","format":"Explainer","hook":"Navigation satellites are flying clocks; your phone measures tiny time differences to find you.","scene":"Each satellite broadcasts a timestamp; receivers compare signals to triangulate position.","coreFact":"Global navigation systems place precise atomic clocks on satellites orbiting Earth. A receiver calculates distance to each satellite from how long signals take to arrive, then intersects those ranges to estimate location. Relativistic effects slightly shift satellite clocks relative to ground, so corrections are built into the system. Urban canyons and indoors weaken accuracy without supplemental sensors.","whyItMatters":"Shipping, aviation, and synchronized power grids depend on timing signals derived from the same satellite networks.","rabbitHole":"How do dual-frequency GPS signals reduce ionospheric error compared with single-frequency fixes?"}'::jsonb, '[]'::jsonb, 'review', null),
('encryption-at-rest', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"encryption-at-rest","title":"Encrypting Data at Rest","domain":"Technology","format":"Explainer","hook":"Locked phones scramble stored files so disks alone do not reveal contents.","scene":"A key derived from your passcode or secure chip protects files even if hardware is stolen.","coreFact":"Encryption at rest transforms data into ciphertext on storage media using secret keys. Full-disk and file-level approaches differ in granularity. Hardware security modules or trusted platform modules can guard keys separately from the main processor. Without the key, forensic access sees pseudorandom bytes, though poorly implemented systems may leak keys through software bugs.","whyItMatters":"Lost laptops and recycled drives make at-rest encryption a baseline control for organizations handling personal data.","rabbitHole":"What is the difference between symmetric keys used for bulk encryption and asymmetric keys used for key exchange?"}'::jsonb, '[]'::jsonb, 'review', null),
('supply-chain-safety-stock', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"supply-chain-safety-stock","title":"Safety Stock vs Just-in-Time","domain":"Current Affairs","format":"Explainer","hook":"Lean inventories save money until a shock proves expensive—planners weigh both sides constantly.","scene":"Factories and retailers choose how much buffer to keep when demand or shipping wobbles.","coreFact":"Just-in-time systems minimize warehouse costs by syncing deliveries closely with production schedules. Safety stock adds extra inventory to absorb supplier delays or demand spikes. Carrying buffer ties up cash and storage; skipping it raises outage risk when ports, weather, or component shortages disrupt flows. Many firms blend strategies by item criticality.","whyItMatters":"Empty shelves during global disruptions revived public debate about resilience versus efficiency in supply networks.","rabbitHole":"Which industries legally require minimum stockpiles regardless of corporate JIT preferences?"}'::jsonb, '[]'::jsonb, 'review', null),
('renewable-intermittency', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"renewable-intermittency","title":"Why Renewables Need Flexible Backup","domain":"Current Affairs","format":"Explainer","hook":"Solar and wind output swing with weather—grids must balance supply and demand every second.","scene":"Operators combine forecasts, storage, transmission, and dispatchable plants to keep frequency stable.","coreFact":"Variable renewable generation rises and falls with sun and wind, not with customer clicks. Grid operators use weather models, geographic diversity, hydro storage, batteries, and fast-ramping plants to match load. Interconnecting regions trades surpluses for deficits. Long-duration storage and demand response programs remain active engineering and policy topics worldwide.","whyItMatters":"Electricity price spikes and blackout prevention strategies increasingly mention flexibility, not only total megawatts installed.","rabbitHole":"How do negative wholesale power prices appear when renewable output exceeds local demand?"}'::jsonb, '[]'::jsonb, 'review', null),
('misinformation-correction', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"misinformation-correction","title":"How Fact-Checks Are Structured","domain":"Current Affairs","format":"Explainer","hook":"Professional fact-checking follows repeatable steps—even when headlines feel instantaneous.","scene":"Teams locate original sources, contact experts, and publish ratings with evidence links.","coreFact":"Fact-check organizations typically trace claims to primary documents, datasets, or dated media. Reviewers document methodology, disclose uncertainties, and classify verdicts using transparent rubrics. Corrections policies address errors publicly. Studies show corrections spread more slowly than original false claims, so repeat exposure and context labels are active research areas—not partisan tricks by themselves.","whyItMatters":"Platforms and classrooms alike borrow fact-check formats to teach source verification skills.","rabbitHole":"What does academic research say about “backfire effects” when corrections challenge deeply held beliefs?"}'::jsonb, '[]'::jsonb, 'review', null),
('photosynthesis-equation', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"photosynthesis-equation","title":"Photosynthesis in One Mechanism","domain":"Science","format":"Explainer","hook":"Plants turn light into stored chemical energy using a process you can summarize in a single equation.","scene":"Chloroplasts capture photons, split water, and fix carbon dioxide into sugars.","coreFact":"Photosynthesis converts light energy, carbon dioxide, and water into glucose and oxygen. Light-dependent reactions in thylakoid membranes generate ATP and NADPH; Calvin-cycle enzymes in the stroma assemble carbon skeletons. Efficiency varies by species and conditions; only part of incoming light becomes biomass. The oxygen we breathe is a by-product of water splitting.","whyItMatters":"Crop yields, forest carbon storage, and algae biofuel research all hinge on tuning or mimicking this pathway.","rabbitHole":"Why do C4 and CAM plants add extra steps compared with classic C3 photosynthesis?"}'::jsonb, '[]'::jsonb, 'review', null),
('herd-immunity-threshold', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"herd-immunity-threshold","title":"Herd Immunity as a Threshold Idea","domain":"Science","format":"Explainer","hook":"When enough people are immune, pathogens struggle to find new hosts—mathematically and practically.","scene":"Each infection generates a reproduction number depending on contacts and susceptibility.","coreFact":"Herd immunity describes the share of immune individuals needed to shrink epidemic growth on average. The threshold rises with contagiousness: more transmissible agents need higher coverage. Immunity may come from vaccination or prior infection, and waning immunity lowers effective coverage over time. Public-health teams model thresholds; they are guides, not magic off-switches.","whyItMatters":"Vaccine schedule debates and school outbreak policies reference these models when setting coverage goals.","rabbitHole":"How does heterogeneous mixing—some people contacting many others—change simple herd-immunity formulas?"}'::jsonb, '[]'::jsonb, 'review', null),
('crispr-gene-edit', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"crispr-gene-edit","title":"CRISPR as Molecular Scissors","domain":"Science","format":"Explainer","hook":"Bacteria borrowed from yogurt science became a tool to snip DNA at chosen addresses.","scene":"Guide RNA matches a target sequence; Cas enzymes cut DNA so cells repair or insert new code.","coreFact":"CRISPR systems use programmable RNA to direct nucleases like Cas9 to specific genomic sequences. Double-strand breaks trigger repair pathways that can disable genes or insert templates. Labs apply the tool in agriculture, medicine research, and diagnostics under varying regulatory oversight. Off-target cuts and delivery into tissues remain active safety engineering problems.","whyItMatters":"Clinical trials and crop breeding headlines often mention CRISPR without explaining the cut-and-repair loop.","rabbitHole":"What do base editors and prime editors change compared with classic CRISPR cutting?"}'::jsonb, '[]'::jsonb, 'review', null),
('metric-prefixes', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"metric-prefixes","title":"Reading Metric Prefixes","domain":"General Knowledge","format":"Explainer","hook":"Kilo-, mega-, giga- are not random—they are standardized powers of ten.","scene":"Prefixes scale units so writers can express tiny or huge quantities with the same base measure.","coreFact":"The International System of Units attaches prefixes to meters, grams, seconds, and derived units. Kilo means ×10³; mega ×10⁶; giga ×10⁹; milli ×10⁻³; micro ×10⁻⁶. Consistent prefixes reduce conversion errors in science, computing, and medicine. Some fields retain non-SI units historically, but SI prefixes appear worldwide on packaging and datasheets.","whyItMatters":"Misreading mega- as milli- has caused real engineering and dosage mistakes—prefix literacy is a safety skill.","rabbitHole":"Why did SI adopt k for kilo while computer science sometimes uses K for 1024 in binary contexts?"}'::jsonb, '[]'::jsonb, 'review', null),
('leap-year-rule', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"leap-year-rule","title":"Why Leap Years Exist","domain":"General Knowledge","format":"Explainer","hook":"Earth’s year is not exactly 365 days—calendars add a day occasionally to stay aligned with seasons.","scene":"Without correction, solstice dates would drift through the months over centuries.","coreFact":"A tropical year is about 365.2422 days. The Gregorian calendar adds February 29 in years divisible by 4, except centuries unless divisible by 400. That pattern keeps equinoxes roughly stable for civic and agricultural scheduling. Older Julian calendars drifted faster because they ignored century exceptions.","whyItMatters":"Software timers, payroll cycles, and sports schedules all embed leap-day rules that broke systems when ignored.","rabbitHole":"How do lunar calendars handle drift differently from solar calendars like the Gregorian one?"}'::jsonb, '[]'::jsonb, 'review', null),
('time-zones-offset', 'card', array['curious']::text[], null, array[]::text[], array[]::text[], null, '{"id":"time-zones-offset","title":"Time Zones as Offsets, Not Physics","domain":"General Knowledge","format":"Explainer","hook":"Clocks change at political borders—time zones follow agreements, not pure longitude math alone.","scene":"Countries pick standard offsets from Coordinated Universal Time, sometimes splitting regions for convenience.","coreFact":"The globe divides into roughly 24 standard zones, each about 15 degrees of longitude wide in theory. Actual borders zigzag to keep nations or economic regions on one clock. Daylight-saving shifts add seasonal offsets in some jurisdictions. Aviation and computing store instants in UTC, converting for display.","whyItMatters":"Meeting invites and transaction timestamps confuse people when offsets and DST rules differ by country.","rabbitHole":"Why do some countries abolish daylight saving while neighbors keep it?"}'::jsonb, '[]'::jsonb, 'review', null),
('feed-proto-black-death', 'post', array['curious']::text[], 'History', array['Medieval', 'pandemic']::text[], array[]::text[], null, '{"id":"feed-proto-black-death","parentCardId":"black-death","type":"slides","title":"When the Black Death Rewired Europe","hook":"A pandemic did not just kill—it reshaped wages, faith, and the map of power.","domain":"History","topics":["Medieval","pandemic"],"formatLabel":"Historical moment","estimatedSeconds":75,"art":{"src":"/stories/black-death.svg","alt":"Black Death in medieval Europe"},"slides":[{"id":"bd-hook","type":"hook","eyebrow":"Curiosity","heading":"Death changed who had leverage","body":"Could a plague in the 1300s really raise peasants’ wages?"},{"id":"bd-context","type":"context","eyebrow":"Context","body":"In the mid-1300s, plague moved along trade routes and hit crowded towns and farms across Eurasia within a few years."},{"id":"bd-reveal","type":"reveal","eyebrow":"The reveal","body":"Fewer workers meant higher wages and weaker serf obligations in many places. Cities saw guilds and councils gain leverage as elites competed for mobile taxpayers."},{"id":"bd-meaning","type":"meaning","eyebrow":"Why it matters","body":"Sudden death still reshapes labor markets and trust in institutions—historians call it shock that accelerates trends already underway."},{"id":"bd-takeaway","type":"takeaway","eyebrow":"Takeaway","body":"Mass mortality rearranges who must be paid and which stories societies tell to make sense of sudden loss.","emphasis":"Post-COVID labor debates echo medieval negotiations over who owes whom a living."}],"deepDive":{"cardId":"black-death","defaultMode":"explainer"},"zoneRefs":[{"zoneId":"roman-empire","stepIndex":0}]}'::jsonb, '[]'::jsonb, 'review', null),
('feed-proto-roman-concrete', 'post', array['curious']::text[], 'Technology', array['Ancient World', 'materials']::text[], array[]::text[], null, '{"id":"feed-proto-roman-concrete","parentCardId":"roman-concrete","type":"video","title":"Roman Concrete That Outlasted Empire","hook":"Engineers today are reverse-engineering a recipe the Romans never wrote down.","domain":"Technology","topics":["Ancient World","materials"],"formatLabel":"How it works","estimatedSeconds":240,"art":{"src":"/stories/roman-concrete.svg","alt":"Roman concrete structures"},"video":{"provider":"youtube","youtubeId":"qL0BB2PRY7k","poster":"/stories/roman-concrete.svg","title":"Roman Concrete That Outlasted Empire","creator":"Verified catalog source","caption":"Harbor breakwaters and the Pantheon dome still stand while much modern Portland cement cracks within decades."},"deepDive":{"cardId":"roman-concrete","defaultMode":"explainer"},"zoneRefs":[{"zoneId":"roman-empire","stepIndex":0}]}'::jsonb, '[]'::jsonb, 'review', null),
('feed-proto-comparative-advantage', 'post', array['curious']::text[], 'Economics', array['trade']::text[], array[]::text[], null, '{"id":"feed-proto-comparative-advantage","parentCardId":"comparative-advantage","type":"slides","title":"Comparative Advantage Is About Opportunity Cost","hook":"Countries trade not because they are “best,” but because each gives up less of something else.","domain":"Economics","topics":["trade"],"formatLabel":"Counterintuitive fact","estimatedSeconds":70,"art":{"src":"/stories/comparative-advantage.svg","alt":"Trade and specialization"},"slides":[{"id":"ca-hook","type":"hook","eyebrow":"Curiosity","heading":"Being worse can still win","body":"Why would a country export goods it makes more slowly than its neighbor?"},{"id":"ca-context","type":"context","eyebrow":"Context","body":"David Ricardo’s insight separates absolute productivity from what you sacrifice to produce one more unit."},{"id":"ca-reveal","type":"reveal","eyebrow":"The reveal","body":"Trade gains come from specializing where your opportunity cost is lowest—even if another country is faster at everything."},{"id":"ca-meaning","type":"meaning","eyebrow":"Why it matters","body":"Sanctions, tariffs, and reshoring debates often ignore that efficiency is about relative sacrifice, not bragging rights."},{"id":"ca-takeaway","type":"takeaway","eyebrow":"Takeaway","body":"Ask “compared to what else could we be doing?” before declaring a industry “uncompetitive.”"}],"deepDive":{"cardId":"comparative-advantage","defaultMode":"explainer"},"zoneRefs":[{"zoneId":"indian-economy-basics","stepIndex":4}]}'::jsonb, '[]'::jsonb, 'review', null),
('feed-proto-plate-boundaries', 'post', array['curious']::text[], 'Geography', array['Science & Invention', 'geology']::text[], array[]::text[], null, '{"id":"feed-proto-plate-boundaries","parentCardId":"plate-boundaries","type":"video","title":"Plate Boundaries Explain Earthquakes and Volcanoes","hook":"Continents drift slowly, but their edges collide with sudden force.","domain":"Geography","topics":["Science & Invention","geology"],"formatLabel":"Scientific mechanism","estimatedSeconds":200,"art":{"src":"/stories/plate-boundaries.svg","alt":"Tectonic plates"},"video":{"provider":"youtube","youtubeId":"p-vNSqUy0l4","poster":"/stories/plate-boundaries.svg","title":"Plate Boundaries Explain Earthquakes and Volcanoes","creator":"Verified catalog source","caption":"Divergent, convergent, and transform boundaries each produce distinct quake and eruption patterns you can map."},"deepDive":{"cardId":"plate-boundaries","defaultMode":"explainer"},"zoneRefs":[{"zoneId":"world-geography-essentials","stepIndex":1}]}'::jsonb, '[]'::jsonb, 'review', null),
('feed-proto-wifi', 'post', array['curious']::text[], 'Technology', array['Technology', 'networks']::text[], array[]::text[], null, '{"id":"feed-proto-wifi","parentCardId":"how-wifi-works","type":"slides","title":"How Wi‑Fi Actually Moves Your Data","hook":"Your router is a tiny radio station juggling dozens of conversations at once.","domain":"Technology","topics":["Technology","networks"],"formatLabel":"Technology explainer","estimatedSeconds":80,"art":{"src":"/stories/how-wifi-works.svg","alt":"Wi-Fi router concept"},"slides":[{"id":"wifi-hook","type":"hook","eyebrow":"Curiosity","heading":"Invisible traffic control","body":"Why does Wi‑Fi feel fine until everyone streams video at once?"},{"id":"wifi-context","type":"context","eyebrow":"Context","body":"Wi‑Fi uses radio on specific bands. Your device and router negotiate who speaks when using shared rules."},{"id":"wifi-reveal","type":"reveal","eyebrow":"The reveal","body":"Data rides as packets. The access point schedules airtime; interference and walls weaken signals; newer standards add wider channels and smarter scheduling."},{"id":"wifi-meaning","type":"meaning","eyebrow":"Why it matters","body":"Mesh networks, fiber backhaul, and honest ISP capacity matter as much as the sticker speed on the box."},{"id":"wifi-takeaway","type":"takeaway","eyebrow":"Takeaway","body":"When Wi‑Fi lags, check airtime competition before blaming “the internet.”"}],"deepDive":{"cardId":"how-wifi-works","defaultMode":"explainer"},"zoneRefs":[{"zoneId":"technology-basics","stepIndex":0}]}'::jsonb, '[]'::jsonb, 'review', null),
('feed-proto-berlin-wall', 'post', array['curious']::text[], 'History', array['Modern Era']::text[], array[]::text[], null, '{"id":"feed-proto-berlin-wall","parentCardId":"berlin-wall","type":"video","title":"Berlin Wall: Concrete That Split a City","hook":"A barrier meant to stop people leaving became a symbol of the Cold War’s end.","domain":"History","topics":["Modern Era"],"formatLabel":"Historical moment","estimatedSeconds":220,"art":{"src":"/stories/berlin-wall.svg","alt":"Berlin Wall"},"video":{"provider":"youtube","youtubeId":"A9fQPzZ1-hg","poster":"/stories/berlin-wall.svg","title":"Berlin Wall: Concrete That Split a City","creator":"Verified catalog source","caption":"East Germany sealed borders to halt emigration; checkpoints, propaganda, and escape attempts turned a city into two daily realities."},"deepDive":{"cardId":"berlin-wall","defaultMode":"story"}}'::jsonb, '[]'::jsonb, 'review', null),
('feed-proto-germ-theory', 'post', array['curious']::text[], 'Science', array['Science & Invention']::text[], array[]::text[], null, '{"id":"feed-proto-germ-theory","parentCardId":"germ-theory","type":"slides","title":"Germ Theory Was Not Obvious","hook":"Doctors once blamed “bad air” while surgeons refused to wash hands.","domain":"Science","topics":["Science & Invention"],"formatLabel":"Myth versus reality","estimatedSeconds":72,"art":{"src":"/stories/germ-theory.svg","alt":"Microbes and medicine"},"slides":[{"id":"gt-hook","type":"hook","eyebrow":"Curiosity","heading":"Invisible killers","body":"If germs are everywhere, why did hospitals resist handwashing for decades?"},{"id":"gt-context","type":"context","eyebrow":"Context","body":"Miasma theory blamed foul air. Semmelweis linked childbed fever to unwashed hands; Pasteur and Koch later tied specific microbes to disease."},{"id":"gt-reveal","type":"reveal","eyebrow":"The reveal","body":"Evidence accumulated through experiments, microscopy, and epidemiology—not a single overnight flip in beliefs."},{"id":"gt-meaning","type":"meaning","eyebrow":"Why it matters","body":"Public health still fights misinformation by showing mechanisms people can picture, not just issuing orders."},{"id":"gt-takeaway","type":"takeaway","eyebrow":"Takeaway","body":"When a practice saves lives but feels inconvenient, expect resistance until the story of “why” sticks."}],"deepDive":{"cardId":"germ-theory","defaultMode":"explainer"}}'::jsonb, '[]'::jsonb, 'review', null),
('feed-proto-monsoon', 'post', array['curious']::text[], 'Geography', array['Geography', 'climate']::text[], array[]::text[], null, '{"id":"feed-proto-monsoon","parentCardId":"monsoon-pattern","type":"slides","title":"Monsoons Are a Geographic Engine","hook":"Seasonal wind reversals feed billions—and one failed season can ripple through markets.","domain":"Geography","topics":["Geography","climate"],"formatLabel":"Geographic surprise","estimatedSeconds":68,"art":{"src":"/stories/monsoon-pattern.svg","alt":"Monsoon winds"},"slides":[{"id":"mo-hook","type":"hook","eyebrow":"Curiosity","heading":"A clock made of wind","body":"Why does South Asia’s rainy season arrive like clockwork—until it doesn’t?"},{"id":"mo-context","type":"context","eyebrow":"Context","body":"Land heats faster than ocean; pressure gradients pull moist air inland, then reverse as continents cool."},{"id":"mo-reveal","type":"reveal","eyebrow":"The reveal","body":"Monsoon timing shapes planting, hydropower, and shipping routes. El Niño and ice loss can shift the rhythm."},{"id":"mo-meaning","type":"meaning","eyebrow":"Why it matters","body":"Climate models treat monsoon stability as a food-security and migration variable, not a weather footnote."},{"id":"mo-takeaway","type":"takeaway","eyebrow":"Takeaway","body":"Watch monsoon forecasts when reading global grain prices—they connect sky to grocery shelves."}],"deepDive":{"cardId":"monsoon-pattern","defaultMode":"explainer"},"zoneRefs":[{"zoneId":"world-geography-essentials","stepIndex":2}]}'::jsonb, '[]'::jsonb, 'review', null),
('feed-proto-printing-press', 'post', array['curious']::text[], 'Technology', array['Renaissance']::text[], array[]::text[], null, '{"id":"feed-proto-printing-press","parentCardId":"printing-press","type":"video","title":"Gutenberg’s Press and the Info Explosion","hook":"Movable type did not create literacy overnight, but it changed who could argue in public.","domain":"Technology","topics":["Renaissance"],"formatLabel":"Technology explainer","estimatedSeconds":210,"art":{"src":"/stories/printing-press.svg","alt":"Printing press"},"video":{"provider":"youtube","youtubeId":"_YqYtdPUis4","poster":"/stories/printing-press.svg","title":"Gutenberg’s Press and the Info Explosion","creator":"Verified catalog source","caption":"Around 1450 in Mainz, craftsmen combined metal type, oil ink, and a screw press to print pages in quantity."},"deepDive":{"cardId":"printing-press","defaultMode":"story"},"zoneRefs":[{"zoneId":"technology-basics","stepIndex":5}]}'::jsonb, '[]'::jsonb, 'review', null),
('feed-proto-money-multiplier', 'post', array['curious']::text[], 'Economics', array['Economics', 'banking']::text[], array[]::text[], null, '{"id":"feed-proto-money-multiplier","parentCardId":"money-multiplier","type":"slides","title":"The Money Multiplier Chain Reaction","hook":"Banks do not lend a fixed pile of cash—they create deposits that ripple through the system.","domain":"Economics","topics":["Economics","banking"],"formatLabel":"Economic chain reaction","estimatedSeconds":74,"art":{"src":"/stories/money-multiplier.svg","alt":"Banking and money supply"},"slides":[{"id":"mm-hook","type":"hook","eyebrow":"Curiosity","heading":"Where does new money go?","body":"If only the central bank prints money, why do textbooks talk about a “multiplier”?"},{"id":"mm-context","type":"context","eyebrow":"Context","body":"When a bank makes a loan, it credits a borrower’s deposit account—creating a new deposit matched by a loan asset."},{"id":"mm-reveal","type":"reveal","eyebrow":"The reveal","body":"Reserve requirements and capital rules limit how far that chain runs. The multiplier is a model of repeated lending, not magic duplication."},{"id":"mm-meaning","type":"meaning","eyebrow":"Why it matters","body":"Rate hikes, liquidity tools, and bank stress tests all aim at this plumbing—not just the printing press."},{"id":"mm-takeaway","type":"takeaway","eyebrow":"Takeaway","body":"Follow the deposit–loan loop when news says “banks are tightening credit.”"}],"deepDive":{"cardId":"money-multiplier","defaultMode":"explainer"},"zoneRefs":[{"zoneId":"indian-economy-basics","stepIndex":5}]}'::jsonb, '[]'::jsonb, 'review', null),
('upsc-governor-assent', 'ca_post', array['upsc']::text[], null, array[]::text[], array['GS2']::text[], '2026-11-14', '{"id":"upsc-governor-assent","kind":"current-affairs","dateKey":"2026-11-14","gs":"GS2","gsArea":"Polity","head":"Can a Governor just sit on a state bill?","what":"States keep going to court over bills left pending with their Governors for months. Punjab, Tamil Nadu and Kerala have all taken this to the Supreme Court since 2023.","background":"Article 200 gives the Governor four options on a bill passed by the state legislature: give assent, withhold assent, return it for reconsideration, or reserve it for the President.","facts":["==Art 200==: the Governor’s options on state bills","==Art 201==: bills reserved for the President","Money bills cannot be returned for reconsideration","If the House passes a returned bill again, the Governor shall not withhold assent","2023, State of Punjab case: the Supreme Court said a Governor cannot keep a bill pending indefinitely"],"chapterId":"polity-governor","why":"Centre–state relations, the Governor’s discretion versus the elected government, and whether the Constitution needs time limits. Use it in GS2 answers on federalism.","sources":[{"publisher":"Constitution of India","title":"Articles 163, 200, 201"},{"publisher":"Supreme Court of India","title":"State of Punjab v. Principal Secretary to the Governor of Punjab (2023)"}],"minutes":2,"sample":true}'::jsonb, '[{"publisher":"Constitution of India","title":"Articles 163, 200, 201"},{"publisher":"Supreme Court of India","title":"State of Punjab v. Principal Secretary to the Governor of Punjab (2023)"}]'::jsonb, 'review', null),
('upsc-mpc-repo', 'ca_post', array['upsc']::text[], null, array[]::text[], array['GS3']::text[], '2026-11-14', '{"id":"upsc-mpc-repo","kind":"current-affairs","dateKey":"2026-11-14","gs":"GS3","gsArea":"Economy","head":"Who actually decides the repo rate?","what":"Every Monetary Policy Committee meeting ends with a repo rate decision that moves loan rates across the country.","background":"Since 2016, the repo rate is set by a six-member Monetary Policy Committee, not by the RBI Governor alone.","facts":["Set up under ==Section 45ZB, RBI Act 1934== (amended 2016)","6 members: 3 from the RBI including the Governor, 3 external members appointed by the Centre","The Governor has a casting vote in a tie","Inflation target: ==4% CPI==, with a band of 2–6%","Meets at least four times a year"],"why":"Links inflation, growth and monetary policy in GS3. Mains asks about inflation targeting and how independent the MPC really is.","sources":[{"publisher":"RBI Act, 1934","title":"Sections 45ZA–45ZB"},{"publisher":"Reserve Bank of India","title":"Monetary Policy Committee"}],"minutes":2,"sample":true}'::jsonb, '[{"publisher":"RBI Act, 1934","title":"Sections 45ZA–45ZB"},{"publisher":"Reserve Bank of India","title":"Monetary Policy Committee"}]'::jsonb, 'review', null),
('upsc-great-indian-bustard', 'ca_post', array['upsc']::text[], null, array[]::text[], array['GS3']::text[], '2026-11-14', '{"id":"upsc-great-indian-bustard","kind":"current-affairs","dateKey":"2026-11-14","gs":"GS3","gsArea":"Environment","head":"Why power lines matter for the Great Indian Bustard","what":"Protecting the Great Indian Bustard keeps returning to the news because of overhead power lines in its Thar desert habitat.","background":"The bustard is a heavy bird with poor forward vision. It flies into overhead power lines, many of them built for solar and wind projects in the Thar.","facts":["IUCN status: ==Critically Endangered==","Schedule I, Wildlife (Protection) Act 1972","State bird of Rajasthan","Main habitat: Desert National Park, Jaisalmer","2024, M.K. Ranjitsinh case: the Supreme Court recognised a right against the adverse effects of climate change"],"why":"Conservation versus clean energy is a classic GS3 trade-off. Use it for answers on biodiversity, renewable energy and environmental law.","sources":[{"publisher":"IUCN Red List","title":"Ardeotis nigriceps"},{"publisher":"Supreme Court of India","title":"M.K. Ranjitsinh v. Union of India (2024)"}],"minutes":2,"sample":true}'::jsonb, '[{"publisher":"IUCN Red List","title":"Ardeotis nigriceps"},{"publisher":"Supreme Court of India","title":"M.K. Ranjitsinh v. Union of India (2024)"}]'::jsonb, 'review', null),
('upsc-western-disturbance', 'ca_post', array['upsc']::text[], null, array[]::text[], array['GS1']::text[], '2026-11-14', '{"id":"upsc-western-disturbance","kind":"current-affairs","dateKey":"2026-11-14","gs":"GS1","gsArea":"Geography","head":"What a western disturbance is, and why wheat farmers care","what":"Each winter, western disturbances bring rain and snow to north-west India and show up in weather news.","background":"A western disturbance is a low-pressure system that forms over the Mediterranean region and is carried east by the subtropical westerly jet stream.","facts":["Origin: Mediterranean and west Asia","Carried by the ==subtropical westerly jet==","Winter rain in Punjab, Haryana, Delhi and western UP","Snowfall in the western Himalayas","Helps rabi crops, especially ==wheat=="],"chapterId":"geography-climate","why":"Links climatology in GS1 with agriculture in GS3. Mains angle: changing patterns of western disturbances and what that means for farming and Himalayan snow.","sources":[{"publisher":"India Meteorological Department","title":"Glossary"}],"minutes":2,"sample":true}'::jsonb, '[{"publisher":"India Meteorological Department","title":"Glossary"}]'::jsonb, 'review', null),
('upsc-wto-appellate-body', 'ca_post', array['upsc']::text[], null, array[]::text[], array['GS2']::text[], '2026-11-14', '{"id":"upsc-wto-appellate-body","kind":"current-affairs","dateKey":"2026-11-14","gs":"GS2","gsArea":"International relations","head":"Why the WTO’s top trade court has been empty since 2019","what":"Trade disputes keep piling up at the WTO with no final court to hear appeals, and its reform comes up at every ministerial meeting.","background":"WTO disputes go to a panel first, and either side can appeal to the Appellate Body. Since December 2019 it has had too few members to hear any appeal, because new appointments have been blocked.","facts":["WTO set up in ==1995== by the Marrakesh Agreement; headquarters in Geneva","Appellate Body: 7 members, 3 hear each appeal","Non-functional since ==December 2019==","An appeal “into the void” leaves a panel ruling unenforced","Some members use an interim appeal arbitration arrangement (MPIA); India has not joined it"],"why":"Rules-based trade, India’s own disputes, and reform of global institutions. Use it in GS2 answers on international institutions and GS3 answers on trade.","sources":[{"publisher":"World Trade Organization","title":"Dispute settlement: Appellate Body"},{"publisher":"World Trade Organization","title":"Understanding on Rules and Procedures Governing the Settlement of Disputes"}],"minutes":2,"sample":true}'::jsonb, '[{"publisher":"World Trade Organization","title":"Dispute settlement: Appellate Body"},{"publisher":"World Trade Organization","title":"Understanding on Rules and Procedures Governing the Settlement of Disputes"}]'::jsonb, 'review', null),
('exp:upsc-governor-assent', 'explainer', array['upsc']::text[], null, array[]::text[], array['GS2']::text[], null, '{"id":"upsc-governor-assent","title":"The Governor and state bills","gs":"GS2","gsArea":"Polity","oneLine":"Article 200 gives the Governor four choices on a state bill. The courts have said sitting on it forever is not one of them.","context":"Since 2023, several states have gone to the Supreme Court over bills their Governors held for months or years. The question each time: is the Governor bound by a deadline, and by the advice of the elected government?","staticLink":"Arts 153–162 set up the Governor’s office. Art 163: the Governor acts on the aid and advice of the council of ministers, except where the Constitution gives discretion. Art 200: options on bills. Art 201: bills reserved for the President. Art 361: the Governor’s personal immunity.","facts":["Four options under Art 200: assent, withhold, return, reserve","Money bills cannot be returned","A bill passed again after return: the Governor shall not withhold assent","Sarkaria Commission (1988): reserve bills for the President only in rare cases","Punchhi Commission (2010): suggested a six-month limit for decisions on bills"],"argumentsFor":"A check on bills that may be unconstitutional. Reserving a bill for the President can protect national interest.","argumentsAgainst":"An unelected office can stall an elected legislature. With no time limit, the power is open to misuse for political ends.","wayForward":"Time limits by convention or amendment, clear grounds for reserving bills, and more Centre–state dialogue through the Inter-State Council (Art 263).","mainsPrompt":"Examine the Governor’s powers over assent to state bills. Should the Constitution set time limits?","sources":[{"publisher":"Constitution of India","title":"Articles 163, 200, 201, 263"},{"publisher":"Supreme Court of India","title":"State of Punjab v. Principal Secretary to the Governor of Punjab (2023)"},{"publisher":"Inter-State Council Secretariat","title":"Reports of the Sarkaria (1988) and Punchhi (2010) Commissions"}],"reviewed":true}'::jsonb, '[{"publisher":"Constitution of India","title":"Articles 163, 200, 201, 263"},{"publisher":"Supreme Court of India","title":"State of Punjab v. Principal Secretary to the Governor of Punjab (2023)"},{"publisher":"Inter-State Council Secretariat","title":"Reports of the Sarkaria (1988) and Punchhi (2010) Commissions"}]'::jsonb, 'review', null),
('exp:anti-defection-law', 'explainer', array['upsc']::text[], null, array[]::text[], array['GS2']::text[], null, '{"id":"anti-defection-law","title":"The anti-defection law","gs":"GS2","gsArea":"Polity","oneLine":"The Tenth Schedule lets a legislator be disqualified for switching parties, with a few exceptions.","context":"Floor-crossing in the 1960s to 80s brought down governments. “Aaya Ram, Gaya Ram” comes from a Haryana MLA who changed parties three times in one day in 1967.","staticLink":"The 52nd Amendment Act, 1985 added the Tenth Schedule. The 91st Amendment Act, 2003 removed the one-third “split” exception and capped the size of ministries.","facts":["Grounds: giving up party membership, or voting or abstaining against the whip without permission","An independent who joins a party after election is disqualified","A nominated member may join a party within six months of taking their seat","Merger exception: two-thirds of the legislature party must agree","The Speaker or Chairman decides; Kihoto Hollohan (1992) made that decision open to judicial review"],"argumentsFor":"Keeps governments stable and respects the mandate voters gave a party.","argumentsAgainst":"Curbs a legislator’s freedom to vote by conscience, strengthens party leaderships, and leaves decisions with a Speaker who may be partisan or slow.","wayForward":"In 2020 the Supreme Court asked Speakers to decide within three months and asked Parliament to consider an independent tribunal. The Dinesh Goswami Committee (1990) suggested decisions by the President or Governor on the Election Commission’s advice.","mainsPrompt":"Has the anti-defection law achieved its purpose? Suggest reforms.","sources":[{"publisher":"Constitution of India","title":"Tenth Schedule"},{"publisher":"Supreme Court of India","title":"Kihoto Hollohan v. Zachillhu (1992)"},{"publisher":"Supreme Court of India","title":"Keisham Meghachandra Singh v. Speaker, Manipur Legislative Assembly (2020)"}],"reviewed":true}'::jsonb, '[{"publisher":"Constitution of India","title":"Tenth Schedule"},{"publisher":"Supreme Court of India","title":"Kihoto Hollohan v. Zachillhu (1992)"},{"publisher":"Supreme Court of India","title":"Keisham Meghachandra Singh v. Speaker, Manipur Legislative Assembly (2020)"}]'::jsonb, 'review', null),
('polity-governor#0', 'chapter_card', array['upsc']::text[], 'Polity', array[]::text[], array['GS2']::text[], null, '{"type":"Concept","title":"Two hats","body":"The Governor is the ==constitutional head of the state== and also the Centre’s link to it. Art 153 provides a Governor for each state; one person can hold the post for two or more states.","cite":"Constitution of India, Art 153"}'::jsonb, '[{"title":"Constitution of India, Art 153"}]'::jsonb, 'published', now()),
('polity-governor#1', 'chapter_card', array['upsc']::text[], 'Polity', array[]::text[], array['GS2']::text[], null, '{"type":"Appointment","title":"Chosen by the President","body":"Appointed by the President by warrant under hand and seal (Art 155). Holds office during the ==pleasure of the President== (Art 156); the normal term is five years.","cite":"Constitution of India, Arts 155–156"}'::jsonb, '[{"title":"Constitution of India, Arts 155–156"}]'::jsonb, 'published', now()),
('polity-governor#2', 'chapter_card', array['upsc']::text[], 'Polity', array[]::text[], array['GS2']::text[], null, '{"type":"Qualifications","title":"Only two in the text","body":"A citizen of India who has completed ==35 years== of age (Art 157). Cannot be a member of Parliament or a state legislature, or hold an office of profit (Art 158).","cite":"Constitution of India, Arts 157–158"}'::jsonb, '[{"title":"Constitution of India, Arts 157–158"}]'::jsonb, 'published', now()),
('polity-governor#3', 'chapter_card', array['upsc']::text[], 'Polity', array[]::text[], array['GS2']::text[], null, '{"type":"Article","title":"Aid and advice","body":"Art 163: a council of ministers headed by the Chief Minister aids and advises the Governor, ==except where the Constitution allows discretion==. If a question arises whether a matter is discretionary, the Governor’s decision is final.","cite":"Constitution of India, Art 163"}'::jsonb, '[{"title":"Constitution of India, Art 163"}]'::jsonb, 'published', now()),
('polity-governor#4', 'chapter_card', array['upsc']::text[], 'Polity', array[]::text[], array['GS2']::text[], null, '{"type":"Article","title":"Four options on a bill","body":"Under Art 200 the Governor can ==assent, withhold, return== (not a money bill) or ==reserve== it for the President. A bill passed again after being returned cannot be withheld.","cite":"Constitution of India, Arts 200–201"}'::jsonb, '[{"title":"Constitution of India, Arts 200–201"}]'::jsonb, 'published', now()),
('polity-governor#5', 'chapter_card', array['upsc']::text[], 'Polity', array[]::text[], array['GS2']::text[], null, '{"type":"Article","title":"Ordinances","body":"Art 213: when the legislature is not in session, the Governor can issue an ordinance. It must be laid before the legislature and lapses ==six weeks== after it reassembles.","cite":"Constitution of India, Art 213"}'::jsonb, '[{"title":"Constitution of India, Art 213"}]'::jsonb, 'published', now()),
('polity-governor#6', 'chapter_card', array['upsc']::text[], 'Polity', array[]::text[], array['GS2']::text[], null, '{"type":"Common confusion","title":"Governor vs President on bills","body":"Both can give or withhold assent and return a non-money bill. Only the Governor has the extra option to ==reserve== a bill for someone else: the President.","cite":"Constitution of India, Arts 111, 200"}'::jsonb, '[{"title":"Constitution of India, Arts 111, 200"}]'::jsonb, 'published', now()),
('polity-governor#7', 'chapter_card', array['upsc']::text[], 'Polity', array[]::text[], array['GS2']::text[], null, '{"type":"Asked like this","title":"How Prelims tests it","body":"Statement questions mix up who can do what: reserve a bill, issue an ordinance, report on the failure of constitutional machinery. Learn the Article next to each power.","cite":"Constitution of India, Arts 200, 213, 356"}'::jsonb, '[{"title":"Constitution of India, Arts 200, 213, 356"}]'::jsonb, 'published', now()),
('geography-climate#0', 'chapter_card', array['upsc']::text[], 'Geography', array[]::text[], array['GS1']::text[], null, '{"type":"Concept","title":"A monsoon climate","body":"India’s climate is called ==monsoon type==: the defining feature is a seasonal reversal of winds, with a wet summer and a dry winter over most of the country.","cite":"India Meteorological Department"}'::jsonb, '[{"title":"India Meteorological Department"}]'::jsonb, 'published', now()),
('geography-climate#1', 'chapter_card', array['upsc']::text[], 'Geography', array[]::text[], array['GS1']::text[], null, '{"type":"Concept","title":"Why the Himalayas matter","body":"The Himalayas block cold winds from Central Asia in winter and hold back the monsoon winds in summer, so the north stays warmer and wetter than its latitude suggests.","cite":"India Meteorological Department"}'::jsonb, '[{"title":"India Meteorological Department"}]'::jsonb, 'published', now()),
('geography-climate#2', 'chapter_card', array['upsc']::text[], 'Geography', array[]::text[], array['GS1']::text[], null, '{"type":"Concept","title":"Western disturbances","body":"Winter rain in the north-west comes from low-pressure systems from the ==Mediterranean== region, carried in by the westerly jet. It is small in amount but valuable for rabi crops.","cite":"India Meteorological Department, Glossary"}'::jsonb, '[{"title":"India Meteorological Department, Glossary"}]'::jsonb, 'published', now()),
('geography-climate#3', 'chapter_card', array['upsc']::text[], 'Geography', array[]::text[], array['GS1']::text[], null, '{"type":"Concept","title":"Two jet streams","body":"In winter a ==subtropical westerly jet== lies south of the Himalayas. In summer a ==tropical easterly jet== blows over the southern Peninsula.","cite":"India Meteorological Department"}'::jsonb, '[{"title":"India Meteorological Department"}]'::jsonb, 'published', now()),
('geography-climate#4', 'chapter_card', array['upsc']::text[], 'Geography', array[]::text[], array['GS1']::text[], null, '{"type":"Date","title":"Onset and spread","body":"The monsoon reaches Kerala around ==1 June== (give or take about a week) and normally covers the whole country by early to mid-July.","cite":"India Meteorological Department, monsoon onset criteria"}'::jsonb, '[{"title":"India Meteorological Department, monsoon onset criteria"}]'::jsonb, 'published', now()),
('geography-climate#5', 'chapter_card', array['upsc']::text[], 'Geography', array[]::text[], array['GS1']::text[], null, '{"type":"Term","title":"Mango showers","body":"Pre-monsoon showers in Kerala and coastal Karnataka that help mangoes ripen early. In Bengal and Assam the spring evening thunderstorms are called ==Kalbaisakhi==.","cite":"India Meteorological Department"}'::jsonb, '[{"title":"India Meteorological Department"}]'::jsonb, 'published', now()),
('geography-climate#6', 'chapter_card', array['upsc']::text[], 'Geography', array[]::text[], array['GS1']::text[], null, '{"type":"Common confusion","title":"Tamil Nadu’s rainy season","body":"The Tamil Nadu coast gets most of its rain in ==October–December==, from the northeast monsoon, not in June–September.","cite":"India Meteorological Department"}'::jsonb, '[{"title":"India Meteorological Department"}]'::jsonb, 'published', now()),
('geography-climate#7', 'chapter_card', array['upsc']::text[], 'Geography', array[]::text[], array['GS1']::text[], null, '{"type":"Term","title":"Loo","body":"Hot, dry, gusty winds that blow over the northern plains on May and June afternoons.","cite":"India Meteorological Department"}'::jsonb, '[{"title":"India Meteorological Department"}]'::jsonb, 'published', now())
